function validate([tree]) {
  if (!Array.isArray(tree) || tree.length === 0) return 'tree is a non-empty list of values with null closing each group of children.';
  if (tree.length > 1 && tree[1] !== null) return 'The root value must be followed by a null.';
  const isValue = value => Number.isInteger(value) && value >= -(2 ** 31) && value < 2 ** 31;
  if (!isValue(tree[0])) return 'The list starts with the root value, a 32-bit integer.';
  const values = [tree[0]];
  let owner = 0;
  for (let i = 2; i < tree.length; i++) {
    if (owner >= values.length) return 'Each group of children needs a node before it to own it.';
    if (tree[i] === null) {
      owner++;
      continue;
    }
    if (!isValue(tree[i])) return 'Node values are 32-bit integers.';
    values.push(tree[i]);
  }
  if (values.length > 50000) return 'The tree has at most 5 * 10^4 nodes.';
  if (new Set(values).size !== values.length) return 'Node values must be unique.';
  return null;
}

