function adapt(input, solve, kit) {
  const [values] = input;
  class Node {
    constructor(val, children = []) { this.val = val; this.children = children; }
  }
  // Rebuild the tree: nodes appear in breadth-first order, so nodes[owner] owns the group being read.
  const root = new Node(values[0]);
  const nodes = [root];
  let owner = 0;
  for (let i = 2; i < values.length; i++) {
    if (values[i] === null) {
      owner++;
      continue;
    }
    const child = new Node(values[i]);
    nodes[owner].children.push(child);
    nodes.push(child);
  }
  // Scramble the nodes with a fixed pseudo-random order derived from the values, keeping the root away from both ends.
  let seed = values.length * 7919 + 17;
  for (const value of values) if (value !== null) seed = (seed * 31 + value) % 2147483647;
  if (seed <= 0) seed += 2147483646;
  const shuffled = nodes.slice();
  for (let k = shuffled.length - 1; k > 0; k--) {
    seed = (seed * 48271) % 2147483647;
    const j = seed % (k + 1);
    [shuffled[k], shuffled[j]] = [shuffled[j], shuffled[k]];
  }
  const at = shuffled.indexOf(root);
  if (shuffled.length > 2 && (at === 0 || at === shuffled.length - 1)) {
    const middle = Math.floor(shuffled.length / 2);
    [shuffled[at], shuffled[middle]] = [shuffled[middle], shuffled[at]];
  }
  const result = solve(shuffled);
  if (result === undefined) throw new Error('The solution did not return a value.');
  if (!nodes.includes(result)) throw new Error('Return one of the node objects from tree.');
  // Serialize the tree that hangs from the returned node, refusing anything that is not a tree.
  const out = [result.val, null];
  const order = [result];
  const seen = new Set(order);
  for (let k = 0; k < order.length; k++) {
    if (!Array.isArray(order[k].children)) throw new Error('Every node needs a children array.');
    for (const child of order[k].children) {
      if (!child || typeof child !== 'object') throw new Error('children may only hold nodes.');
      if (seen.has(child)) throw new Error('The tree must not be changed: a node is reached twice.');
      seen.add(child);
      order.push(child);
      out.push(child.val);
    }
    out.push(null);
  }
  while (out.length > 0 && out[out.length - 1] === null) out.pop();
  return out;
}

