function findRoot(tree) {
  let xor = 0;
  for (const node of tree) {
    xor ^= node.val;
    for (const child of node.children) {
      xor ^= child.val;
    }
  }
  for (const node of tree) {
    if (node.val === xor) {
      return node;
    }
  }
  return null;
}

