function findRoot(tree) {
  // Try each node and ask every other node whether it lists that node as a child.
  for (const candidate of tree) {
    let hasParent = false;
    for (const other of tree) {
      if (other.children.includes(candidate)) hasParent = true;
    }
    if (!hasParent) return candidate;
  }
  return null;
}

