function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 900 + pick(95) : 1 + pick(10);
  // Unique values: a shuffled run of distinct integers, sometimes shifted to include zero and negatives.
  const shift = rand() < 0.3 ? -pick(2 * n) : rand() < 0.1 ? 2147483647 - 4 * n : 0;
  const pool = Array.from({ length: 3 * n }, (_, k) => k + 1 + shift);
  for (let k = pool.length - 1; k > 0; k--) {
    const j = pick(k + 1);
    [pool[k], pool[j]] = [pool[j], pool[k]];
  }
  const shape = rand();
  const nodes = [{ val: pool[0], children: [] }];
  while (nodes.length < n) {
    // Deep trees grow from recent nodes, wide trees from a few early ones, mixed trees from anywhere.
    let parent;
    if (shape < 0.3) parent = nodes[Math.max(0, nodes.length - 1 - pick(3))];
    else if (shape < 0.5) parent = nodes[pick(Math.min(nodes.length, 3))];
    else parent = nodes[pick(nodes.length)];
    const child = { val: pool[nodes.length], children: [] };
    parent.children.push(child);
    nodes.push(child);
  }
  const values = [nodes[0].val, null];
  const order = [nodes[0]];
  for (let k = 0; k < order.length; k++) {
    for (const child of order[k].children) {
      order.push(child);
      values.push(child.val);
    }
    values.push(null);
  }
  while (values[values.length - 1] === null) values.pop();
  return [values];
}
